class Computer:
    class CPU:
        def label(self): return 'processor'
chip = Computer.CPU()
print(chip.label())

class Parser:
    class Result:
        def __init__(self, ok): self.ok = ok
result = Parser.Result(True)
print(result.ok)

class Address:
    def __init__(self, city): self.city = city
class Customer:
    def __init__(self, address): self.address = address
c = Customer(Address('Pune'))
print(c.address.city)
